style.css:
/* Roblox custom background */
html, body {
    background: url("https://i.pinimg.com/736x/c2/85/21/c28521fb062bbab52adaca5eef84bc14.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
}

/* Make black/gray panels transparent */
[class*="navbar"],
[class*="header"],
[class*="footer"],
[class*="content"],
[class*="section"],
[class*="container"],
[class*="panel"] {
    background: rgba(20, 20, 20, 0.75) !important;
}
